"""Fast deterministic dense-tiling circle packing for n=26 circles."""
import numpy as np


def _radii_from_centers(centers, n_sweeps=200):
    """Maximize sum of radii for fixed centers via constraint projection.

    Each radius is bounded by its wall distance and, for every pair, by the
    center-to-center gap. We iteratively project onto the feasible region
    (a polymorphic / successive-over-relaxation relaxation of the LP) which
    converges to a near-optimal feasible radius assignment.
    """
    n = centers.shape[0]
    d = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            d[i, j] = d[j, i] = np.hypot(centers[i, 0] - centers[j, 0],
                                         centers[i, 1] - centers[j, 1])
    wall = np.array([min(c[0], c[1], 1.0 - c[0], 1.0 - c[1]) for c in centers])
    r = wall.copy()
    for _ in range(n_sweeps):
        changed = False
        for i in range(n):
            # wall constraint
            if r[i] > wall[i]:
                r[i] = wall[i]
                changed = True
            # pairwise constraints
            for j in range(n):
                if i == j:
                    continue
                rem = d[i, j] - r[j]
                if rem < r[i]:
                    r[i] = max(rem, 0.0)
                    changed = True
        if not changed:
            break
    return r


def _evaluate(centers):
    centers = np.asarray(centers, dtype=float)
    n = centers.shape[0]
    radii = _radii_from_centers(centers)
    # feasibility safety clamp (numerical)
    for i in range(n):
        for j in range(i + 1, n):
            dd = np.hypot(centers[i, 0] - centers[j, 0],
                          centers[i, 1] - centers[j, 1])
            s = radii[i] + radii[j]
            if s > dd and s > 0:
                f = dd / s
                radii[i] *= f
                radii[j] *= f
    return radii, float(np.sum(radii))


def construct_packing():
    n = 26
    best_centers = None
    best_radii = None
    best_sum = -1.0

    # ---- Family A: 5x5 grid, center site removed ----
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    base = []
    for y in coords:
        for x in coords:
            if not (abs(x - 0.5) < 1e-9 and abs(y - 0.5) < 1e-9):
                base.append([x, y])
    base = np.array(base, dtype=float)
    assert len(base) == n, len(base)

    candidates = [base.copy()]

    # ---- Family A2: 5x5 grid with a different site removed (corner) ----
    for rm in [(0.1, 0.1), (0.9, 0.1), (0.1, 0.9), (0.9, 0.9)]:
        pts = []
        for y in coords:
            for x in coords:
                if not (abs(x - rm[0]) < 1e-9 and abs(y - rm[1]) < 1e-9):
                    pts.append([x, y])
        pts = np.array(pts, dtype=float)
        if len(pts) == n:
            candidates.append(pts)

    # ---- Family B: 6x5 lattice, two sites removed ----
    xs6 = np.linspace(0.1, 0.9, 6)
    ys5 = np.linspace(0.1, 0.9, 5)
    lattice = np.array([[x, y] for y in ys5 for x in xs6], dtype=float)  # 30
    for rm in [(0.1, 0.1), (0.9, 0.1), (0.1, 0.9), (0.9, 0.9)]:
        keep = [p for p in lattice if not (abs(p[0] - rm[0]) < 1e-9 and
                                           abs(p[1] - rm[1]) < 1e-9)]
        if len(keep) == n:
            candidates.append(np.array(keep, dtype=float))

    # ---- Family C: row layers [6,5,5,5,5] ----
    def row_layer(count, y):
        if count == 1:
            return np.array([[0.5, y]])
        return np.column_stack([np.linspace(0.1, 0.9, count),
                                np.full(count, y)])
    ys = np.linspace(0.1, 0.9, 5)
    cfgs = [[6, 5, 5, 5, 5], [5, 6, 5, 5, 5], [6, 6, 5, 5, 4],
            [6, 5, 6, 5, 4], [5, 5, 6, 5, 5]]
    for cfg in cfgs:
        if sum(cfg) != n:
            continue
        pts = np.vstack([row_layer(c, y) for c, y in zip(cfg, ys)])
        candidates.append(pts)

    # ---- Family D: hexagonal rows [6,5,6,5,4] with half-spacing offsets ----
    dx = 1.0 / 6.0
    for cfg in [[6, 5, 6, 5, 4], [5, 6, 5, 6, 4], [6, 5, 5, 6, 4]]:
        if sum(cfg) != n:
            continue
        parts = []
        for k, (c, y) in enumerate(zip(cfg, ys)):
            if c == 1:
                parts.append(np.array([[0.5, y]]))
            else:
                if k % 2 == 0:
                    xs = np.linspace(0.1, 0.9, c)
                else:
                    span = 1.0 / c
                    xs = np.linspace(span / 2 + 0.0, 1.0 - span / 2, c)
                parts.append(np.column_stack([xs, np.full(c, y)]))
        candidates.append(np.vstack(parts))

    # ---- Deterministic local relaxation: nudge toward wall slack ----
    def relax(centers):
        c = centers.copy()
        for _ in range(40):
            # recompute radii, find binding, move centers with wall slack
            radii = _radii_from_centers(c, 60)
            moved = False
            for i in range(n):
                x, y = c[i]
                # push toward the corner giving largest min-wall
                for cx in (0.0, 1.0):
                    for cy in (0.0, 1.0):
                        nx, ny = x + 0.02 * np.sign(cx - x), y + 0.02 * np.sign(cy - y)
                        if 0.02 <= nx <= 0.98 and 0.02 <= ny <= 0.98:
                            trial = c.copy()
                            trial[i] = [nx, ny]
                            _, s = _evaluate(trial)
                            if s > _evaluate(c)[1] + 1e-9:
                                c = trial
                                moved = True
            if not moved:
                break
        return c

    for cand in candidates:
        r, s = _evaluate(cand)
        if s > best_sum:
            best_sum, best_centers, best_radii = s, cand.copy(), r.copy()

    # refine the single best candidate with relaxation
    if best_centers is not None:
        rc = relax(best_centers)
        r2, s2 = _evaluate(rc)
        if s2 > best_sum:
            best_sum, best_centers, best_radii = s2, rc.copy(), r2.copy()

    return best_centers, best_radii, best_sum
# EVOLVE-BLOCK-END

