def _radii_from_centers(centers):
    """Guaranteed-feasible radius assignment maximizing the sum.

    Start each radius at its wall distance, then enforce every pairwise
    non-overlap constraint by shrinking the larger of the two circles.
    The result satisfies r_i <= wall_i and r_i + r_j <= dist(i,j) for all i,j.
    """
    n = centers.shape[0]
    d = np.zeros((n, n))
    for i in range(n):
        for j in range(i + 1, n):
            d[i, j] = d[j, i] = np.hypot(centers[i, 0] - centers[j, 0],
                                         centers[i, 1] - centers[j, 1])
    wall = np.array([min(c[0], c[1], 1.0 - c[0], 1.0 - c[1]) for c in centers])
    r = wall.copy()
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                gap = d[i, j]
                s = r[i] + r[j]
                if s > gap:
                    excess = s - gap
                    # shrink the larger circle (keeps the smaller intact)
                    if r[i] >= r[j]:
                        cut = min(r[i], excess)
                        r[i] -= cut
                        excess -= cut
                        if excess > 0:
                            r[j] -= excess
                    else:
                        cut = min(r[j], excess)
                        r[j] -= cut
                        excess -= cut
                        if excess > 0:
                            r[i] -= excess
                    if r[i] < 0:
                        r[i] = 0.0
