def construct_packing():
    # 5x5 grid at 0.1,0.3,0.5,0.7,0.9 with the center site removed -> 24 sites
    # plus 2 more to reach 26.
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    centers = []
    for y in coords:
        for x in coords:
            if abs(x - 0.5) < 1e-9 and abs(y - 0.5) < 1e-9:
                continue
            centers.append([x, y])
    # add two interior-ish sites (the empty center and one offset) to reach 26
    centers.append([0.5, 0.5])
    centers.append([0.5, 0.7])
    # dedupe
    seen = set()
    uniq = []
    for p in centers:
        k = (round(p[0], 6), round(p[1], 6))
        if k not in seen:
            seen.add(k)
            uniq.append(p)
    centers = uniq
    if len(centers) > 26:
        centers = centers[:26]

    # radii: start at wall distance, then shrink to satisfy all pairwise gaps
    n = len(centers)
    radii = []
    for (x, y) in centers:
        radii.append(min(x, y, 1.0 - x, 1.0 - y))
    for _ in range(500):
