        for i in range(n):
            for j in range(i + 1, n):
                dx = centers[i][0] - centers[j][0]
                dy = centers[i][1] - centers[j][1]
                gap = (dx * dx + dy * dy) ** 0.5
                s = radii[i] + radii[j]
                if s > gap:
                    excess = s - gap
                    if radii[i] >= radii[j]:
                        cut = min(radii[i], excess)
                        radii[i] -= cut
                        excess -= cut
                        if excess > 0:
                            radii[j] -= excess
                    else:
                        cut = min(radii[j], excess)
                        radii[j] -= cut
