"""Circle packing n=26: scipy pipeline with dense-tiling inits + more budget."""
import numpy as np
from scipy.optimize import linprog, minimize


def solve_max_radii_lp(centers):
    n = centers.shape[0]
    c = -np.ones(n)
    A_rows = []
    b_vals = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
            row = np.zeros(n)
            row[i] = 1
            row[j] = 1
            A_rows.append(row)
            b_vals.append(d)
    for i in range(n):
        x, y = centers[i]
        b_dist = min(x, y, 1 - x, 1 - y)
        row = np.zeros(n)
        row[i] = 1
        A_rows.append(row)
        b_vals.append(b_dist)
    A = np.array(A_rows)
    b = np.array(b_vals)
    bounds = [(0, None)] * n
    result = linprog(c, A_ub=A, b_ub=b, bounds=bounds, method='highs')
    if result.success:
        return np.maximum(result.x, 0)
    return compute_max_radii_fallback(centers)


def compute_max_radii_fallback(centers):
    n = centers.shape[0]
    radii = np.ones(n)
    for i in range(n):
        x, y = centers[i]
        radii[i] = min(x, y, 1 - x, 1 - y)
    for _ in range(200):
        for i in range(n):
            for j in range(i + 1, n):
                dist = np.sqrt(np.sum((centers[i] - centers[j]) ** 2))
                if radii[i] + radii[j] > dist:
                    scale = dist / (radii[i] + radii[j])
                    radii[i] *= scale
                    radii[j] *= scale
    return radii


def lp_sum(centers):
    return np.sum(solve_max_radii_lp(centers))


def hex_lattice(s):
    dy = s * np.sqrt(3) / 2
    pts = []
    row = 0
    y = 0.02
    while y <= 0.98:
        x_offset = (s / 2) if (row % 2 == 1) else 0
        x = 0.02 + x_offset
        while x <= 0.98:
            pts.append([x, y])
            x += s
        y += dy
        row += 1
    return np.array(pts)


def grid5_remove(remove):
    coords = [0.1, 0.3, 0.5, 0.7, 0.9]
    pts = []
    for y in coords:
        for x in coords:
            if abs(x - remove[0]) < 1e-9 and abs(y - remove[1]) < 1e-9:
                continue
            pts.append([x, y])
    return np.array(pts[:26], dtype=float)


def construct_packing():
    n = 26
    best_centers = None
    best_sum = -1

    inits = []

    # dense-tiling inits: 5x5 grid with various sites removed
    for rm in [(0.5, 0.5), (0.1, 0.1), (0.9, 0.1), (0.1, 0.9), (0.9, 0.9)]:
        inits.append(grid5_remove(rm))

    # hex lattice inits
    for s in [0.15, 0.16, 0.17]:
        pts = hex_lattice(s)
        if len(pts) >= 26:
            dists = np.sqrt((pts[:, 0] - 0.5) ** 2 + (pts[:, 1] - 0.5) ** 2)
            idx = np.argsort(dists)
